import{_ as o,c as a,o as t,ag as s}from"./chunks/framework.DZ_cNctr.js";const u=JSON.parse('{"title":"Changelog","description":"What changed in the Find Nuclei Viewer, newest first.","frontmatter":{"title":"Changelog","description":"What changed in the Find Nuclei Viewer, newest first."},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md"}'),n={name:"changelog.md"};function i(r,e,l,d,h,g){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><h2 id="_2026-11-06" tabindex="-1">2026-11-06 <a class="header-anchor" href="#_2026-11-06" aria-label="Permalink to &quot;2026-11-06&quot;">​</a></h2><ul><li><strong>3D works offline.</strong> The offline install now includes it, so 3D opens without a connection. <a href="/docs/install-and-offline.html">Installing and working offline</a></li><li><strong>The viewer tells you when 3D cannot reach your graphics card.</strong> You see it when you open a 3D image and above the 2D | 3D switch, with a link to what to turn on. This helps most in Chrome on Linux. <a href="/docs/guides/3d-rendering.html#requirements-and-limits">Requirements</a></li><li><strong>Fixed:</strong> a browser with WebGL turned off now gets a clear message, instead of waiting on Loading dataset forever.</li></ul><h2 id="_2026-11-04" tabindex="-1">2026-11-04 <a class="header-anchor" href="#_2026-11-04" aria-label="Permalink to &quot;2026-11-04&quot;">​</a></h2><ul><li><strong>Every image now opens in 3D in MIP.</strong> Composite is one click away. <a href="/docs/guides/3d-rendering.html">3D Rendering</a></li><li><strong>The 3D toolbar no longer covers the image.</strong> It sits in its own band above the panels, and one click hides it. Drawing tools open from <strong>Annotate</strong>, and rarely changed settings moved to <strong>View</strong>, <strong>Show</strong> and <strong>Rotation</strong>. <a href="/docs/guides/3d-rendering.html">3D Rendering</a></li><li><strong>3D tells you what to do next.</strong> Choosing a tool shows a short tip, as in 2D. Turn tips off in <strong>View</strong>. A question that needs an answer now shows in the middle of the screen, and goes by itself once the read is done.</li><li><strong>Structures start when you draw.</strong> In Structure, the first shape starts a new structure, and Enter or Esc finishes it. <strong>Add</strong> and <strong>Cut</strong> say what a shape does to it. Brush now shows only in Structure.</li><li><strong>Reset also clears the region.</strong></li><li><strong>The notice that 3D shows a coarse level now goes by itself</strong>, after a few seconds.</li><li><strong>See one area of a very large image in 3D at full detail.</strong> Choose <strong>Region</strong> and draw a box on the XY panel, or zoom in and click <strong>Region from view</strong>. 3D then shows only that box, at the finest detail that fits, and the box tells you the detail and the size of the read before you let go. The box can also cover fewer z-sections: drag it on the XZ or YZ panel, or zoom those panels and click <strong>Region from view</strong>. That reads less and leaves room for more detail. <strong>Clear region</strong> goes back, and <strong>Link</strong> carries the box. <a href="/docs/guides/region.html">3D Region</a></li><li><strong>Images too large for a 3D volume can now open in 3D at less detail.</strong> An image with no pyramid, or one whose smallest level is still too large, offers to read itself once at lower detail in X and Y. You see the size first, and you can stop the read. <a href="/docs/guides/3d-rendering.html">3D Rendering</a></li><li><strong>Zeiss CZI files compressed with JPEG XR now open.</strong> Whole-slide scans with a stored pyramid too, nothing to convert. <a href="/docs/guides/zeiss-czi.html">Zeiss CZI files</a></li><li><strong>Zeiss CZI files with illumination, view, phase, rotation or block open as a list.</strong> Pick one from the dropdown, named after the dimension. <a href="/docs/guides/zeiss-czi.html">Zeiss CZI files</a></li><li><strong>Zeiss CZI files open as they are.</strong> Paste the address of a <code>.czi</code> file, as https or <code>s3://</code>, or drop it from your disk in any browser. Z-stacks, time series, scenes, mosaics and stored pyramids open, and so do Celldiscoverer 7 plates, in Field view. <a href="/docs/guides/zeiss-czi.html">Zeiss CZI files</a></li><li><strong>Plates saved as one CZI per field open as one plate.</strong> Drop the folder, or a zip made without compression, from your disk or by its web address. Wells come from the files&#39; own metadata. A folder with more than one thing shows a list to choose from. <a href="/docs/guides/zeiss-czi.html#plates-saved-as-one-file-per-field">Plates saved as one file per field</a></li><li><strong>Fixed:</strong> in Chrome and Edge, a <code>.ozx</code> file chosen in the Open dialog now reopens from <strong>Recent</strong> without asking for the file again. Messages now use the app&#39;s font.</li><li><strong>Fixed:</strong> a file that stops loading now shows a message instead of waiting forever, and a dropped connection is tried again while a file opens.</li><li><strong>Fixed:</strong> in Safari, Choose File now opens the file you pick.</li></ul><h2 id="_2026-11-03" tabindex="-1">2026-11-03 <a class="header-anchor" href="#_2026-11-03" aria-label="Permalink to &quot;2026-11-03&quot;">​</a></h2><ul><li><strong>Label images in 3D</strong>, as a surface per object or a coloured volume. <a href="/docs/guides/3d-rendering.html#labels-in-3d">Labels in 3D</a></li><li><strong>A label with more than 5,000 objects opens in 3D as a coloured volume</strong>, which shows at once, rather than as surfaces, which would take a while to build. Choose <strong>Surface</strong> to build them anyway. <a href="/docs/guides/3d-rendering.html#labels-in-3d">Labels in 3D</a></li><li><strong>Contour width</strong> from 1 to 5, in 2D and 3D. <a href="/docs/guides/labels.html">Labels</a></li><li><strong>Links carry more:</strong> labels added with <strong>Add URL</strong>, and the 3D camera and label look. <a href="/docs/guides/sharing.html">Sharing views</a></li><li><strong>Planar is now called 2D.</strong> Links and saved views open as before.</li><li><strong>Each mode keeps its view</strong>, and <strong>Recent</strong> reopens an image in the mode you left.</li><li><strong>3D memory</strong> slider in Settings. The CT presets moved there too.</li><li><strong>New 3D example:</strong> a stem cell colony with every nucleus outlined (Allen Institute for Cell Science).</li><li><strong>Fixed:</strong> <strong>Add URL</strong> on a plain image, and a link losing a label&#39;s colour.</li></ul><h2 id="_2026-11-02" tabindex="-1">2026-11-02 <a class="header-anchor" href="#_2026-11-02" aria-label="Permalink to &quot;2026-11-02&quot;">​</a></h2><ul><li><strong>Open a zipped dataset by its address.</strong> Paste the address of an <code>.ozx</code> or <code>.zip</code> file, including a Dropbox file link, and it opens in 2D and in 3D. The viewer reads only the parts it needs, never the whole file. Dropbox file links work, but they are not the best way to share data for viewing: Dropbox takes several seconds to answer each read, so opening a large image can take a minute or more. For data you view often, put it in object storage (S3, R2, GCS) or on any web server that supports range requests. Dropbox folder links, Google Drive, OneDrive and Proton Drive are not supported. <a href="/docs/guides/remote-urls.html#zipped-datasets">Zipped Datasets</a></li></ul><h2 id="_2026-11-01" tabindex="-1">2026-11-01 <a class="header-anchor" href="#_2026-11-01" aria-label="Permalink to &quot;2026-11-01&quot;">​</a></h2><ul><li><strong>See your stack in 3D.</strong> Open an image with several Z planes and click <strong>3D</strong> next to the Z slider, or the 3D badge at the top. Turn it with the mouse. Two side views sit next to the usual one, so you can see a cell from the side. Your colours, your place in the stack and your annotations come along, and come back when you switch back. You need a computer, not a phone or tablet, with a recent Chrome or Edge. It opens images from a web address, a local folder or an <code>.ozx</code> or <code>.zip</code> file. <a href="/docs/guides/3d-rendering.html">3D Rendering</a></li><li><strong>Side views of your stack.</strong> The XY, XZ and YZ views sit side by side, linked by one crosshair. Click a nucleus in one view and the others jump to it, so you see it from the top and from both sides at once.</li><li><strong>Anatomical orientation.</strong> When an image records its anatomical orientation, 3D labels the ends of each axis (superior and inferior, left and right, anterior and posterior). The <strong>Medical</strong> button then shows it the radiological way: superior up, the patient&#39;s right on the left of the screen.</li><li><strong>Two ways to look.</strong> <strong>MIP</strong> shows the brightest signal through the whole depth, good for nuclei, neurons and other bright spots. <strong>Composite</strong> shows solid shapes, with near things in front of far ones.</li><li><strong>3D examples to try.</strong> The Example Gallery now has seven images to explore in 3D near the top, from a zebrafish embryo to a fish skeleton. The new <strong>3D</strong> filter also shows the other images and plates you can switch to 3D yourself. <a href="https://find-nuclei.github.io/?url=https%3A%2F%2Fuk1s3.embassy.ebi.ac.uk%2Fidr%2Fzarr%2Fv0.4%2Fidr0079A%2Fidr0079_images.zarr&amp;c=0%3Aon%3A00FF00%3A5%3A200%3A1.00%2C1%3Aon%3AFF0000%3A10%3A160%3A1.00&amp;mode=3d&amp;rm=composite&amp;cam=25%2C-20%2C1.7" target="_blank" rel="noreferrer">Open the zebrafish in 3D</a></li><li><strong>Share what you see in 3D.</strong> Copy the link while in 3D, and whoever opens it lands in 3D too, with your colours.</li><li><strong>Plates in 3D.</strong> Imaged your plate in several Z planes? Pick a well and a field, then click 3D. You can still move between wells as usual. <a href="/docs/guides/hcs-plates.html">HCS Plates</a></li><li><strong>Analytical Results filter.</strong> The Results filter and badge in the Example Gallery are now called Analytical Results, so it is clear what they mean.</li><li><strong>Saving right after opening.</strong> A change made in the first few seconds after opening an image could fail with &quot;Save failed: Image not found&quot;. It now saves.</li></ul><h2 id="_2026-10-30" tabindex="-1">2026-10-30 <a class="header-anchor" href="#_2026-10-30" aria-label="Permalink to &quot;2026-10-30&quot;">​</a></h2><ul><li><strong>A plate with analysis results, one click away.</strong> BBBC013, a 96-well screen, now opens with masks for 18,648 nuclei and 15,331 cells, and a measurement table behind each mask. Colour the nuclei by a measurement, filter them, or build a phenotype, right on the plate. It is hosted on our site, so it opens fast. <a href="https://find-nuclei.github.io/?url=https%3A%2F%2Ffind-nuclei.github.io%2Fexamples%2Fbbbc013%2FBBBC013.zarr&amp;analyticsUrl=https%3A%2F%2Ffind-nuclei.github.io%2Fexamples%2Fbbbc013%2FBBBC013.zarr.analytics%2F0b1e47a7-stardist-cellpose%2F&amp;tab=labels&amp;c=0%3Aon%3A808080%3A3%3A134%3A1.00%2C1%3Aon%3AFFFFFF%3A1%3A100%3A1.00&amp;v=plate&amp;w=A%2F1&amp;f=0&amp;zm=0.77&amp;xy=4446%2C2322&amp;cm=C&amp;inv=t&amp;bg=%23ffffff&amp;l=ext%3Acells%2Cext%3Anuclei&amp;lv=cells%3Acategory%3Aphenotype_class&amp;ls=cells%3A0.5%3Afc%2Cnuclei%3A1%3Afc%3A808080" target="_blank" rel="noreferrer">Open the example</a> · <a href="/docs/guides/example-plate-results.html">Example: Plate with Results</a></li><li><strong>Find examples with results.</strong> The Example Gallery has two new filters, <strong>Labels</strong> and <strong>Results</strong>, and a <strong>Results</strong> badge on every example that comes with an analysis.</li><li><strong>Links keep your masks.</strong> A copied link, and the address bar, now remember which masks from an analysis are shown, how each is coloured and how it is drawn. Reload the page or reopen the image from Recent, and they come back as you left them.</li><li><strong>One analysis, one group.</strong> In the Labels list, the masks from one analysis sit under one heading, named after the analysis.</li><li><strong>Fixed: masks drawn twice on the plate.</strong> Switching to the whole plate no longer draws every visible mask twice.</li><li><strong>Fixed: blank card in Recent.</strong> A plate opened straight on the whole-plate view now gets its picture in Recent, like any other image.</li></ul><h2 id="_2026-10-23" tabindex="-1">2026-10-23 <a class="header-anchor" href="#_2026-10-23" aria-label="Permalink to &quot;2026-10-23&quot;">​</a></h2><ul><li><strong>Invert one channel.</strong> Brightfield and fluorescence in one view used to fight: the bright background washed out your stains. Now press <strong>INV</strong> next to AUTO, FIT and HIST on the brightfield channel. It turns dark, and your stains shine on top at full brightness, with the cell outlines still in view. A small INV mark on the colour square tells you which channel is flipped. Saved views and shared links remember it. <a href="/docs/guides/channels.html#invert-one-channel">Invert one channel</a></li><li><strong>Clearer colours on Opera Phenix and CellVoyager plates.</strong> Every channel now gets its own colour, so two stains never look the same. On JUMP Cell Painting plates, 488 long now shows yellow next to the red of Alexa 568. Plates you saved keep your colours.</li></ul><h2 id="_2026-10-19" tabindex="-1">2026-10-19 <a class="header-anchor" href="#_2026-10-19" aria-label="Permalink to &quot;2026-10-19&quot;">​</a></h2><ul><li><strong>Yokogawa CellVoyager plates open straight from their folder.</strong> Paste the address of a CV8000 or CV7000 measurement folder, or of its <code>MeasurementDetail.mrf</code>, as https or <code>s3://</code>, or open the folder from disk in Chrome or Edge. The plate opens as soon as the first well is in. JUMP plates from sources 2, 5, 6, 10 and 13 in the Cell Painting Gallery open this way, and six of them are in the Example Gallery. <a href="/docs/guides/yokogawa-plates.html">Yokogawa CellVoyager plates</a></li><li><strong>Harmony V6 plates open too.</strong> An Opera Phenix export with a V6 <code>Index.xml</code> opens like a V5 one, from its folder or its index. <a href="/docs/guides/opera-phenix-plates.html">Opera Phenix plates</a></li><li><strong>Info names the instrument.</strong> The Format line says which CellVoyager made the plate.</li></ul><h2 id="_2026-10-17" tabindex="-1">2026-10-17 <a class="header-anchor" href="#_2026-10-17" aria-label="Permalink to &quot;2026-10-17&quot;">​</a></h2><ul><li><strong>Opera Phenix plates open straight from their index.</strong> Paste the address of a Harmony plate index, as https or <code>s3://</code>, or open its folder from disk in Chrome or Edge. The whole plate opens, well by well, after reading about 1 MB of the index. Opera Phenix plates in the Cell Painting Gallery open this way, such as the JUMP pilot plate CPJUMP1. <a href="/docs/guides/opera-phenix-plates.html">Opera Phenix plates</a></li><li><strong><code>s3://</code> addresses open OME-Zarr too.</strong> Paste <code>s3://bucket/path</code> of a public bucket and the image or plate opens, as from its https address. <a href="/docs/guides/supported-formats.html">Supported Formats</a></li><li><strong>Single-level images open fitted to the window.</strong> An image with one resolution that is larger than the window used to open at 100% and would not zoom out. Now it opens fitted, and zooms out to a quarter of that. <a href="/docs/guides/supported-formats.html">Supported Formats</a></li></ul><h2 id="_2026-10-16" tabindex="-1">2026-10-16 <a class="header-anchor" href="#_2026-10-16" aria-label="Permalink to &quot;2026-10-16&quot;">​</a></h2><ul><li><strong>A zoom sharpens once or twice, not level by level.</strong> It used to sharpen one level of detail at a time, and every wheel turn started it over, so the same area sharpened again and again. Now it waits until the view has been still for about a second and a half, then loads the finest detail that fits in memory in one go. If that would take longer than about 20 seconds, a level in between comes first. Zooming out to the opening view shows it at once with the detail it already had. <a href="/docs/guides/embedding.html#time-lapse-figures">Time-lapse figures</a></li></ul><h2 id="_2026-10-15" tabindex="-1">2026-10-15 <a class="header-anchor" href="#_2026-10-15" aria-label="Permalink to &quot;2026-10-15&quot;">​</a></h2><ul><li><strong>A short time-lapse plays its first loop at full speed on a slow connection.</strong> It used to start early and crawl through the first loop at 2 to 4 frames a second. Now it waits for the whole loop at the detail the connection can load, says when it starts, then plays at the rate you asked for and sharpens in the background. That wait can pass 10 seconds on a slow link, up to about 30 seconds of loading. A longer series, one that does not fit in memory or would take longer than that to load, plays like a video or at an even, slower tempo, and that tempo now keeps up with the connection. <a href="/docs/guides/embedding.html#time-lapse-figures">Time-lapse figures</a></li></ul><h2 id="_2026-10-12" tabindex="-1">2026-10-12 <a class="header-anchor" href="#_2026-10-12" aria-label="Permalink to &quot;2026-10-12&quot;">​</a></h2><ul><li><strong>Time-lapse playback is faster.</strong> Playback no longer waits on timers between frames. It plays from memory at the rate you asked for, up to 30 fps, and each frame is still shown complete. Autoplay starts once the figure is on screen. <a href="/docs/guides/embedding.html#time-lapse-figures">Time-lapse figures</a></li><li><strong>A time-lapse starts without stutter on any connection.</strong> Before it plays, the bar says when it starts: &quot;Loading, starts in about 6 s&quot;. It picks the finest detail it can play without stopping and starts within about 10 seconds. On a slow connection it starts with less detail and sharpens in the background (&quot;Sharpening 12 of 30&quot;). A long series plays like a video, with a few seconds loaded ahead. When even the least detail cannot keep up, it plays at an even, slower tempo. <a href="/docs/guides/embedding.html#time-lapse-figures">Time-lapse figures</a></li><li><strong>The opening view stays in memory.</strong> Zoom back out to it, or further, and playback goes on at once. Zoom in and playback goes on at once from memory, drawn larger, and sharpens one level of detail at a time (&quot;Sharpening 12 of 30, about 2 min&quot;), switching between two frames. A pan to a part never loaded waits as at the start; press Play to go on at once with what is loaded. Long estimates read in minutes. The full viewer shows the same line next to Play. <a href="/docs/guides/embedding.html#time-lapse-figures">Time-lapse figures</a></li><li><strong>Embeds on phones and small screens.</strong> When a viewer is narrower than 480 pixels or lower than 320, and on phones and tablets, the channel panel stays hidden so the image is not covered. Fullscreen brings it back. On a touch screen the bottom bar is always shown. <a href="/docs/guides/embedding.html#on-phones-and-small-screens">Embedding</a></li><li><strong>A bigger memory budget for playback.</strong> The page keeps up to 512 MB of image tiles, or 1 GB on devices that report 8 GB or more. This applies to the full viewer too.</li></ul><h2 id="_2026-10-10" tabindex="-1">2026-10-10 <a class="header-anchor" href="#_2026-10-10" aria-label="Permalink to &quot;2026-10-10&quot;">​</a></h2><ul><li><strong>Several embedded viewers on one page each show their own data.</strong> Two or more viewers on one page, each with its own dataset, now always show their own images, through time-lapse playback, panning and zooming. Before, one viewer could show the other&#39;s image.</li><li><strong>Size and theme apply before the image loads.</strong> A <code>height</code>, <code>width</code> or <code>theme</code> set on a viewer by your page&#39;s script now takes effect at once, not only after the image has loaded. <a href="/docs/guides/embedding.html#multiple-viewers-on-one-page">Embedding</a></li></ul><h2 id="_2026-10-06" tabindex="-1">2026-10-06 <a class="header-anchor" href="#_2026-10-06" aria-label="Permalink to &quot;2026-10-06&quot;">​</a></h2><ul><li><strong>Embedded viewers tell your page what readers do.</strong> Each viewer in an article now reports panning, zooming, channel changes, the z-slice and timepoint, and when it is on screen, as an event your page can listen to. The viewer sends nothing anywhere; your page decides what to keep. Name each figure with <code>id</code> to tell them apart. <a href="/docs/guides/embedding.html#reader-interactions">Embedding</a> · <a href="/docs/guides/reader-analytics.html">Reader Analytics</a></li></ul><h2 id="_2026-09-28" tabindex="-1">2026-09-28 <a class="header-anchor" href="#_2026-09-28" aria-label="Permalink to &quot;2026-09-28&quot;">​</a></h2><ul><li><strong>OME-Zarr version 0.6 files open.</strong> Version 0.6 is the newest version of the OME-Zarr format. Files saved in it now open like any other: from a web link, a folder on your computer or a zip file, with time-lapses, well plates and segmentation labels. <a href="/docs/getting-started.html">Getting started</a></li><li><strong>Zip files open as they are.</strong> To send a dataset as one file, right-click its folder and choose Compress on a Mac, or Send to › Compressed (zipped) folder on Windows. The viewer opens that zip directly, with nothing to unpack. <a href="/docs/guides/local-files.html#making-one">Local files</a></li><li><strong>A clearer message when a file cannot open.</strong> If a file uses an OME-Zarr version the viewer does not support yet, the message now says which version it is and what you can do.</li></ul><h2 id="_2026-09-21" tabindex="-1">2026-09-21 <a class="header-anchor" href="#_2026-09-21" aria-label="Permalink to &quot;2026-09-21&quot;">​</a></h2><ul><li><strong>Time-lapse playback.</strong> A Play button under the time slider, and Space to toggle it. Frames advance one at a time, each shown complete, at four per second by default. Dragging the slider pauses. <a href="/docs/guides/embedding.html#time-lapse-figures">Embedding</a></li><li><strong>Embed code from the toolbar.</strong> The new Embed button turns the current view into an HTML element or a MyST directive, ready to copy, with an autoplay option for time-lapses. Local files are refused with a reason. <a href="/docs/guides/embedding.html#from-a-view-to-an-embed">Embedding</a></li><li><strong>Embed controls read on a white page.</strong> <code>theme=&quot;light&quot;</code> now styles the time slider, the channel panel and the colour picker, not only the buttons. The range tracks lost their grey bar on white. Clicking a channel&#39;s caret closes its open picker instead of reopening it.</li><li><strong><code>autoplay</code> and <code>fps</code> for embeds.</strong> A time-lapse figure in an article can start on its own and pauses while scrolled out of view. <a href="/docs/guides/embedding.html#time-lapse-figures">Embedding</a></li></ul><h2 id="_2026-09-19" tabindex="-1">2026-09-19 <a class="header-anchor" href="#_2026-09-19" aria-label="Permalink to &quot;2026-09-19&quot;">​</a></h2><ul><li><strong>The embed works inside a shadow root.</strong> MyST and Curvenote sites, <em>Elemental Microscopy</em> among them, isolate each widget in a shadow DOM, where the viewer used to fail with &quot;Container not found&quot;. It now finds its own canvas and its own stylesheet wherever it is mounted. <a href="/docs/guides/embedding.html#myst-curvenote-and-shadow-dom">Embedding</a></li><li><strong>A widget module for MyST articles.</strong> <code>embed/v1/widget.mjs</code> follows the <code>any:bundle</code> and anywidget contract, so one directive embeds the viewer with the same attributes as the HTML element. <a href="/docs/guides/embedding.html#myst-curvenote-and-shadow-dom">Embedding</a></li><li><strong><code>grayscale</code> and <code>invert</code> attributes.</strong> The BW and INV toggles of the viewer, for embeds. Inverted nuclei on white look like a printed figure. <a href="/docs/guides/embedding.html#grayscale-and-inverted-views">Embedding</a></li></ul><h2 id="_2026-09-18" tabindex="-1">2026-09-18 <a class="header-anchor" href="#_2026-09-18" aria-label="Permalink to &quot;2026-09-18&quot;">​</a></h2><ul><li><strong>The embed opens the series you asked for.</strong> On a multi-image store, <code>image=&quot;1&quot;</code> and up failed with &quot;Failed to load image metadata&quot; since May, when the viewer started loading only the first series at open time. The embed now asks for the series the same way the viewer does when you navigate to it. Embeds of single-image stores were never affected. <a href="/docs/guides/embedding.html#multi-image-stores">Embedding</a></li></ul><h2 id="_2026-09-02" tabindex="-1">2026-09-02 <a class="header-anchor" href="#_2026-09-02" aria-label="Permalink to &quot;2026-09-02&quot;">​</a></h2><ul><li><strong>Open a dataset packed into a single file.</strong> Drop an <code>.ozx</code> or a <code>.zip</code> onto the viewer, or pick one with <strong>Choose Zipped Dataset</strong>. The viewer reads pieces of the archive as it needs them, so nothing is unpacked and a large dataset opens as fast as a folder. <a href="/docs/guides/local-files.html#a-dataset-in-a-single-file">Local Files</a></li><li><strong>Local data now opens in Safari and Firefox.</strong> A zipped dataset is one file, and every browser can read a file. Dataset folders still need Chrome or Edge, and the viewer now says only that rather than telling those browsers they cannot open local data at all. <a href="/docs/guides/local-files.html#which-browsers-can-do-this">Local Files</a></li><li><strong>Double-click an <code>.ozx</code> to open it.</strong> The installed app now registers the extension, so a dataset opens from Finder or Explorer without finding a browser window first. Chrome and Edge, once installed. <code>.zip</code> is deliberately not registered. <a href="/docs/guides/local-files.html#double-click-to-open">Local Files</a></li><li><strong>Recent zipped datasets reopen as files, not folders.</strong> Clicking one used to ask for a directory, which is not a thing you have when your dataset is a single file. In Chrome and Edge it now asks only for permission; elsewhere it asks for the file. Either way you land back on the same image, annotations and all. <a href="/docs/guides/local-files.html#why-safari-and-firefox-behave-differently">Local Files</a></li><li><strong>The drop overlay promises only what your browser can do.</strong> It said &quot;Drop ZARR folder to open&quot; everywhere, Safari included, where a dropped folder cannot be read at all.</li><li><strong>A plate that lists wells it does not hold says so.</strong> It used to report that the viewer had failed to read a dataset, which sent people to file a bug about a truncated copy. It now names the count it found and suggests checking the copy.</li></ul><h2 id="_2026-09-01" tabindex="-1">2026-09-01 <a class="header-anchor" href="#_2026-09-01" aria-label="Permalink to &quot;2026-09-01&quot;">​</a></h2><ul><li><strong>Drop a folder onto the viewer, not just the start screen.</strong> No going back to close what you have open first. Drag a dataset onto the viewer and it opens there. <a href="/docs/guides/local-files.html#drag-and-drop">Local Files</a></li><li><strong>A drop that would replace your image asks first.</strong> It names what you dropped and what is open, so a stray drag does not cost you your place.</li><li><strong>Edits are no longer lost when you switch images.</strong> A change made just before opening something else could be dropped before it saved. Closing the tab was always safe. Switching was not. It is now.</li></ul><h2 id="_2026-08-31" tabindex="-1">2026-08-31 <a class="header-anchor" href="#_2026-08-31" aria-label="Permalink to &quot;2026-08-31&quot;">​</a></h2><ul><li><strong>Open a folder of datasets and pick one.</strong> When the folder you open holds datasets rather than being one, the viewer lists what it found and opens whichever you click. No trip back to the file manager to drag the same data again, one level down. <a href="/docs/guides/local-files.html#if-the-folder-holds-datasets">Local Files</a></li><li><strong>It looks inside a folder instead of reading its name.</strong> A dataset is recognised by what it contains, so folders named for a codec, a condition, or nothing in particular are found just as readily as ones named something.zarr.</li><li><strong>When the viewer cannot read a dataset, it says so.</strong> Instead of suggesting your folder is misnamed, it tells you the problem is on our side, and gives you a way to say which tool wrote the data so we can fix the reader. <a href="/docs/guides/local-files.html">Local Files</a></li></ul><h2 id="_2026-08-22" tabindex="-1">2026-08-22 <a class="header-anchor" href="#_2026-08-22" aria-label="Permalink to &quot;2026-08-22&quot;">​</a></h2><ul><li><strong>Label order sticks now.</strong> Drag a mask up or down, and it comes back where you left it. Order is also draw order, so this decides which compartment paints over which. <a href="/docs/guides/labels.html#worked-example-multiple-compartments">Labels</a></li><li><strong>Labels you linked yourself keep their order too.</strong> Re-linked masks used to come back in the order the folder declared them, whatever you had chosen. Saves made before this fix are read correctly, so nothing needs re-saving.</li></ul><h2 id="_2026-08-21" tabindex="-1">2026-08-21 <a class="header-anchor" href="#_2026-08-21" aria-label="Permalink to &quot;2026-08-21&quot;">​</a></h2><ul><li><strong>Shared links now carry the whole view.</strong> What you see is what they see. <a href="/docs/guides/sharing.html#what-the-recipient-sees">Sharing Views</a></li><li><strong>Opening a link keeps your own settings.</strong> It changes only what the link names. <a href="/docs/guides/sharing.html">Sharing Views</a></li><li><strong>Links no longer switch on your own labels.</strong> Labels built into a dataset travel with the link. Ones you added yourself stay yours, and the viewer says when a link had one. <a href="/docs/guides/labels.html">Labels</a></li><li><strong>Z-projection travels in the link</strong>, over the whole stack or a slab of it. <a href="/docs/guides/z-projection.html">Z-Projection</a></li><li><strong>Fixed the mean projection.</strong> Deep stacks came out too dark. Worth re-checking anything you measured from one. <a href="/docs/guides/z-projection.html">Z-Projection</a></li><li><strong>Faster Z-projection on deep stacks</strong>, and easier on memory.</li><li><strong>New custom background colour picker.</strong> Black, white, greys, or any colour you like.</li><li><strong>Brightfield images now open on a white background by default.</strong></li><li><strong>A link naming some channels no longer blanks the others.</strong> They keep the settings you already had. <a href="/docs/guides/channels.html">Channels</a></li></ul><h2 id="_2026-08-14" tabindex="-1">2026-08-14 <a class="header-anchor" href="#_2026-08-14" aria-label="Permalink to &quot;2026-08-14&quot;">​</a></h2><ul><li><strong>Install the viewer like an app.</strong> Install it from your browser and it opens from the dock or start menu, in its own window, with no address bar and no tab to lose. <a href="/docs/install-and-offline.html#installing">Installing and Offline</a></li><li><strong>It works with no connection.</strong> The viewer&#39;s own program files are cached on first visit, so it starts and runs offline. Local files open on a plane or behind a firewall exactly as they do online. Remote URLs still need a network, for obvious reasons. <a href="/docs/install-and-offline.html#working-with-no-network">Installing and Offline</a></li><li><strong>Your images are never cached.</strong> Only the program is. Image data is read on demand and never written to the offline cache, by design.</li></ul><h2 id="_2026-08-11" tabindex="-1">2026-08-11 <a class="header-anchor" href="#_2026-08-11" aria-label="Permalink to &quot;2026-08-11&quot;">​</a></h2><ul><li><strong>Inverted display got consistent rules.</strong> INV swaps white and black, and only those: every other channel colour keeps its hue. The canvas background follows the toggle, and channel swatches show the colour that actually lands on the page. <a href="/docs/guides/channels.html">Channels</a></li><li><strong>Contour rendering is much faster on chunked masks.</strong> Label chunks are now read aligned and cached, so outlining no longer multiplies decompression work. Toggling contour, fill or colours reuses cached data instead of re-reading it. <a href="/docs/guides/labels.html">Labels</a></li><li><strong>Improved Contour rendering for large images when zoomed out.</strong> The black outline fades into the fill where objects get too small to hold it, so a plate overview shows coloured objects instead of a black mass.</li><li><strong>Clear All Data now clears everything</strong>, including annotation templates and UI preferences, and the confirmation lists exactly what goes before you commit.</li></ul><h2 id="_2026-08-10" tabindex="-1">2026-08-10 <a class="header-anchor" href="#_2026-08-10" aria-label="Permalink to &quot;2026-08-10&quot;">​</a></h2><ul><li><strong>Analytics and phenotyping.</strong> Attach a measurements table to a segmentation, colour objects by any column, filter by value, then group them into named phenotypes. <a href="/docs/guides/analytics-phenotyping.html">Analytics and Phenotyping</a></li><li><strong>Annotations and templates.</strong> Draw and measure regions in real units. Classify them with reusable colour, class and shortcut templates, and export as CSV or GeoJSON. <a href="/docs/guides/annotations.html">Annotations</a> · <a href="/docs/guides/templates.html">Annotation Templates</a></li><li><strong>Documentation.</strong> Fourteen guides with screenshots, plus a published spec for the analytics data format so other tools can emit something the viewer reads. <a href="/docs/guides/">Guides</a> · <a href="/docs/guides/analytics-format.html">Analytics Data Format</a></li></ul>',53)])])}const m=o(n,[["render",i]]);export{u as __pageData,m as default};
